import math


def _matrix(value, name):
    if isinstance(value, (str, bytes)):
        raise ValueError(name + ' must be a matrix')
    try:
        rows = list(value)
    except TypeError:
        raise ValueError(name + ' must be a matrix') from None
    if not rows:
        raise ValueError(name + ' must not be empty')
    output = []
    width = None
    for row in rows:
        if isinstance(row, (str, bytes)):
            raise ValueError(name + ' has an invalid row')
        try:
            values = list(row)
        except TypeError:
            raise ValueError(name + ' has an invalid row') from None
        if not values or (width is not None and len(values) != width):
            raise ValueError(name + ' must be rectangular')
        width = len(values)
        if any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in values):
            raise ValueError(name + ' contains an invalid number')
        output.append([float(x) for x in values])
    return output


def classify_grids(grids, kernels, biases):
    try:
        raw_kernels = list(kernels)
        raw_biases = list(biases)
        raw_grids = list(grids)
    except TypeError:
        raise ValueError('arguments must be iterable') from None
    if not raw_kernels or len(raw_kernels) != len(raw_biases):
        raise ValueError('kernel and bias counts must match')
    checked_kernels = [_matrix(k, 'kernel') for k in raw_kernels]
    if any(isinstance(b, bool) or not isinstance(b, (int, float)) or not math.isfinite(b) for b in raw_biases):
        raise ValueError('invalid bias')
    checked_grids = [_matrix(g, 'grid') for g in raw_grids]
    all_scores = []
    indices = []
    for grid in checked_grids:
        scores = []
        for kernel, bias in zip(checked_kernels, raw_biases):
            gh, gw, kh, kw = len(grid), len(grid[0]), len(kernel), len(kernel[0])
            if kh > gh or kw > gw:
                raise ValueError('kernel is larger than grid')
            best = 0.0
            for y in range(gh - kh + 1):
                for x in range(gw - kw + 1):
                    value = float(bias) + sum(grid[y + dy][x + dx] * kernel[kh - 1 - dy][kw - 1 - dx] for dy in range(kh) for dx in range(kw))
                    best = max(best, value, 0.0)
            scores.append(float(best))
        all_scores.append(scores)
        indices.append(max(range(len(scores)), key=lambda i: (scores[i], -i)))
    return {'indices': indices, 'scores': all_scores}

